'use client';

import * as React from 'react';
import { RailSidebar } from '@/components/ui/rail-sidebar';
import { DotMatrixChart } from '@/components/ui/charts/dot-matrix-chart';
import { TactileTrendCard } from '@/components/ui/charts/tactile-trend-card';
import { TactileMetricCard, TactileBarCard } from '@/components/ui/charts/tactile-metric-card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { BrandLogo } from '@/components/brand/BrandLogo';
import { Download, RefreshCw, Copy, Check, ArrowUpRight, ShieldCheck, Database, Cpu } from 'lucide-react';
import { cn } from '@/lib/utils';

interface StreamTransaction {
  id: string;
  target: string;
  type: string;
  volume: string;
  latency: string;
  status: 'Settled' | 'Executing' | 'Verified';
}

const STREAM_DATA: StreamTransaction[] = [
  { id: '0x8f2a...c10b', target: 'Batch Auction Core', type: 'Settlement', volume: '$42,850', latency: '4.2ms', status: 'Settled' },
  { id: '0x3e1d...94fa', target: 'Liquid Staking Pool', type: 'Rebalance', volume: '$128,400', latency: '6.1ms', status: 'Verified' },
  { id: '0x7c90...a821', target: 'Order Routing Engine', type: 'Execution', volume: '$18,920', latency: '2.8ms', status: 'Settled' },
  { id: '0x1b44...d590', target: 'Arbitrage Liquidity', type: 'Inflow', volume: '$84,100', latency: '3.4ms', status: 'Executing' },
  { id: '0x99a2...fe33', target: 'Proof Generation Node', type: 'Validation', volume: '$210,000', latency: '12.0ms', status: 'Verified' },
];

export function TactileStudioDashboard() {
  const [activeNav, setActiveNav] = React.useState('overview');
  const [copied, setCopied] = React.useState(false);

  const handleCopyCode = () => {
    navigator.clipboard.writeText(`import { TactileStudioDashboard } from '@/components/blocks/TactileStudioDashboard';

export default function Dashboard() {
  return <TactileStudioDashboard />;
}`);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="w-full rounded-[28px] border border-border/80 bg-card overflow-hidden shadow-tactile flex flex-col md:flex-row min-h-[850px]">
      {/* 1. Architectural Rail Sidebar */}
      <RailSidebar
        activeId={activeNav}
        onSelect={setActiveNav}
        workspaceLogo={<BrandLogo size="xs" variant="minimal" />}
        workspaceName="NickUI Autonomous Systems"
        className="hidden md:flex shrink-0"
      />

      {/* 2. Main Dashboard Viewport */}
      <div className="flex-1 flex flex-col min-w-0 bg-background/50">
        {/* Top Architectural Command Bar */}
        <header className="h-16 px-6 sm:px-8 border-b border-border/70 flex items-center justify-between gap-4 bg-card/60 backdrop-blur-md">
          <div className="flex items-center gap-3">
            <div className="flex items-center gap-2">
              <span className="text-xs font-mono text-text-muted uppercase tracking-wider">Studio /</span>
              <h2 className="text-sm font-medium tracking-tight text-text-primary">
                Executive Operations & Telemetry
              </h2>
            </div>
            <span className="hidden sm:inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-mono font-medium bg-emerald-500/10 text-emerald-500 border border-emerald-500/20">
              <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
              Live Stream
            </span>
          </div>

          <div className="flex items-center gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={handleCopyCode}
              leftIcon={copied ? <Check className="w-3.5 h-3.5 text-emerald-500" /> : <Copy className="w-3.5 h-3.5" />}
              className="text-xs font-mono h-8"
            >
              {copied ? 'Copied Import' : 'Copy Block Code'}
            </Button>
            <Button
              variant="secondary"
              size="sm"
              leftIcon={<Download className="w-3.5 h-3.5" />}
              className="text-xs font-mono h-8"
            >
              Export
            </Button>
          </div>
        </header>

        {/* Scrollable Dashboard Body */}
        <div className="p-6 sm:p-8 space-y-8 overflow-y-auto">
          {/* Row 1: The 3 Reference Metric Widgets */}
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 items-stretch">
            {/* 1. Tactile Balance Node Trajectory Card */}
            <TactileMetricCard
              title="Balance"
              periodLabel="2024"
              value="$94,127"
              deltaText="increase 13%"
              deltaSubtext="vs last year"
              className="w-full max-w-none h-full"
            />

            {/* 2. Tactile Income Bar Highlight Card with Threshold Line */}
            <TactileBarCard
              title="Income"
              periodLabel="This Month"
              value="$12,532"
              deltaText="increase 12%"
              deltaSubtext="vs last month"
              className="w-full max-w-none h-full"
            />

            {/* 3. Dot Matrix Equalizer Revenue Card */}
            <div className="md:col-span-2 xl:col-span-1">
              <DotMatrixChart
                title="REVENUE VELOCITY"
                metric="+326%"
                previousLabel="MAY $3,250"
                currentLabel="JUN $12,392"
                footerTagline="HIGH THROUGHPUT | 2024 | ZERO LOSS"
                className="h-full"
              />
            </div>
          </div>

          {/* Row 2: Deep Trend Curve & Real-Time Settlement Stream */}
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
            {/* Left: Tactile Trend Curve Card with Top Keywords */}
            <div className="lg:col-span-5 w-full">
              <TactileTrendCard
                title="Protocol Volume Trend"
                keywords={['Batch auction', 'Liquid staking derivatives (LSD)', 'Proof rollups']}
                metricLabel="Active Validated Nodes"
                metricValue="824"
                metricDeltaSuperscript="+334"
                percentageDelta="34.4%"
                className="w-full max-w-none"
              />
            </div>

            {/* Right: Architectural Execution Stream Table */}
            <div className="lg:col-span-7 rounded-[26px] border border-border/70 bg-card p-6 sm:p-7 shadow-tactile space-y-4">
              <div className="flex items-center justify-between pb-3 border-b border-border/50">
                <div>
                  <h3 className="text-sm font-medium tracking-tight text-text-primary">
                    Real-Time Settlement Stream
                  </h3>
                  <p className="text-xs text-text-muted mt-0.5">
                    Sub-second consensus telemetry across distributed nodes.
                  </p>
                </div>
                <Badge variant="mono" className="text-[10px]">
                  5 Nodes Active
                </Badge>
              </div>

              {/* Transactions Table */}
              <div className="overflow-x-auto">
                <table className="w-full text-left text-xs">
                  <thead>
                    <tr className="border-b border-border/40 text-text-muted font-mono uppercase text-[10px] tracking-wider">
                      <th className="pb-2.5 font-normal">Transaction ID</th>
                      <th className="pb-2.5 font-normal">Target Node</th>
                      <th className="pb-2.5 font-normal text-right">Volume</th>
                      <th className="pb-2.5 font-normal text-right">Latency</th>
                      <th className="pb-2.5 font-normal text-right">Status</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-border/30 font-mono">
                    {STREAM_DATA.map((tx) => (
                      <tr key={tx.id} className="hover:bg-secondary/40 transition-colors">
                        <td className="py-3 text-text-primary font-medium">{tx.id}</td>
                        <td className="py-3 text-text-secondary font-sans">{tx.target}</td>
                        <td className="py-3 text-right text-text-primary font-medium">{tx.volume}</td>
                        <td className="py-3 text-right text-text-muted">{tx.latency}</td>
                        <td className="py-3 text-right">
                          <span
                            className={cn(
                              'inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-mono',
                              tx.status === 'Settled' && 'bg-emerald-500/10 text-emerald-500 border border-emerald-500/20',
                              tx.status === 'Verified' && 'bg-blue-500/10 text-blue-400 border border-blue-500/20',
                              tx.status === 'Executing' && 'bg-amber-500/10 text-amber-500 border border-amber-500/20'
                            )}
                          >
                            {tx.status}
                          </span>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import * as React from 'react';
import { motion } from 'framer-motion';
import { BarChart2, ChevronDown, MoreHorizontal, ArrowUpRight } from 'lucide-react';
import { cn } from '@/lib/utils';

// ─── 1. TACTILE METRIC CARD (LINE / NODE TRAJECTORY) ──────────────────────────

export interface MetricNodePoint {
  label: string;
  value: number; // 0 to 100
  tooltipValue?: string;
  tooltipSubtext?: string;
}

export interface TactileMetricCardProps extends React.HTMLAttributes<HTMLDivElement> {
  title?: string;
  periodLabel?: string;
  value?: string;
  deltaText?: string;
  deltaSubtext?: string;
  nodes?: MetricNodePoint[];
  initialActiveIndex?: number;
  onMoreClick?: () => void;
  onPeriodClick?: () => void;
}

const DEFAULT_METRIC_NODES: MetricNodePoint[] = [
  { label: 'Jan', value: 72, tooltipValue: '$2,352.96 income', tooltipSubtext: '+12% vs prior' },
  { label: 'Feb', value: 45, tooltipValue: '$1,420.10 income', tooltipSubtext: '-8% vs prior' },
  { label: 'Mar', value: 38, tooltipValue: '$1,190.50 income', tooltipSubtext: '-5% vs prior' },
  { label: 'Apr', value: 52, tooltipValue: '$1,620.00 income', tooltipSubtext: '+4% vs prior' },
  { label: 'May', value: 68, tooltipValue: '$2,140.00 income', tooltipSubtext: '+10% vs prior' },
  { label: 'Jun', value: 64, tooltipValue: '$1,980.20 income', tooltipSubtext: '+2% vs prior' },
  { label: 'Jul', value: 88, tooltipValue: '$3,150.80 income', tooltipSubtext: '+18% vs prior' },
];

export const TactileMetricCard = React.forwardRef<HTMLDivElement, TactileMetricCardProps>(
  (
    {
      className,
      title = 'Balance',
      periodLabel = '2024',
      value = '$94,127',
      deltaText = '+13%',
      deltaSubtext = 'vs last year',
      nodes = DEFAULT_METRIC_NODES,
      initialActiveIndex = 0,
      onMoreClick,
      onPeriodClick,
      ...props
    },
    ref
  ) => {
    const id = React.useId();
    const cleanId = id.replace(/[^a-zA-Z0-9]/g, '');
    const glowGradientId = `columnGlow-${cleanId}`;
    const lineAreaGradientId = `lineArea-${cleanId}`;
    const [activeIndex, setActiveIndex] = React.useState(initialActiveIndex);

    const width = 340;
    const height = 120;
    const paddingX = 20;
    const paddingY = 16;

    const points = nodes.map((node, i) => {
      const x = paddingX + (i / (nodes.length - 1)) * (width - paddingX * 2);
      const y = height - paddingY - (node.value / 100) * (height - paddingY * 2);
      return { x, y, node };
    });

    // Smooth spline calculation
    const pathD = points.reduce((acc, point, i, arr) => {
      if (i === 0) return `M ${point.x},${point.y}`;
      const prev = arr[i - 1];
      const cp1x = prev.x + (point.x - prev.x) / 2;
      const cp1y = prev.y;
      const cp2x = prev.x + (point.x - prev.x) / 2;
      const cp2y = point.y;
      return `${acc} C ${cp1x},${cp1y} ${cp2x},${cp2y} ${point.x},${point.y}`;
    }, '');

    const areaD = `${pathD} L ${points[points.length - 1].x},${height} L ${points[0].x},${height} Z`;
    const activePoint = points[activeIndex] || points[0];

    return (
      <div
        ref={ref}
        className={cn(
          'relative w-full rounded-[26px] border border-border/70 bg-card text-text-primary p-6',
          'shadow-tactile select-none transition-colors overflow-hidden flex flex-col justify-between',
          className
        )}
        {...props}
      >
        {/* Header: Title, Period & Actions */}
        <div className="flex items-center justify-between gap-3 pb-4">
          <div className="flex items-center gap-2">
            <div className="w-6 h-6 rounded-md bg-secondary/80 border border-border/60 flex items-center justify-center text-text-muted">
              <BarChart2 className="w-3.5 h-3.5" />
            </div>
            <span className="text-xs font-medium tracking-tight text-text-primary">{title}</span>
          </div>

          <div className="flex items-center gap-1.5">
            <button
              type="button"
              onClick={onPeriodClick}
              className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-md text-[11px] font-mono bg-secondary/60 border border-border/60 text-text-secondary hover:text-text-primary hover:bg-secondary/90 transition-colors cursor-pointer"
            >
              <span>{periodLabel}</span>
              <ChevronDown className="w-3 h-3 text-text-muted" />
            </button>
            <button
              type="button"
              onClick={onMoreClick}
              aria-label="More options"
              className="w-6 h-6 rounded-md inline-flex items-center justify-center text-text-muted hover:text-text-primary hover:bg-secondary/60 transition-colors cursor-pointer"
            >
              <MoreHorizontal className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>

        {/* Metric Value Row */}
        <div className="flex items-baseline justify-between gap-3 pb-4">
          <div className="text-2xl sm:text-3xl font-mono font-medium tracking-tight text-text-primary">
            {value}
          </div>
          <div className="flex items-center gap-1.5 text-right">
            <span className="inline-flex items-center gap-0.5 px-2 py-0.5 rounded-full text-[10px] font-mono font-medium bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20">
              <ArrowUpRight className="w-3 h-3" />
              {deltaText}
            </span>
            <span className="text-[10px] text-text-muted hidden sm:inline">{deltaSubtext}</span>
          </div>
        </div>

        {/* Chart Canvas Area */}
        <div className="relative w-full pt-2 pb-1">
          {/* Active Tooltip Pill */}
          {activePoint.node.tooltipValue && (
            <motion.div
              key={activeIndex}
              initial={{ opacity: 0, y: -2 }}
              animate={{ opacity: 1, y: 0 }}
              className="absolute z-20 px-2.5 py-1 rounded-lg bg-card border border-border/80 text-text-primary shadow-tactile pointer-events-none"
              style={{
                left: `${Math.min(Math.max(activePoint.x - 55, 6), width - 140)}px`,
                top: `${Math.max(activePoint.y - 44, 0)}px`,
              }}
            >
              <div className="text-[10.5px] font-mono font-medium text-text-primary leading-tight">
                {activePoint.node.tooltipValue}
              </div>
              {activePoint.node.tooltipSubtext && (
                <div className="text-[9.5px] font-mono text-text-muted leading-tight">
                  {activePoint.node.tooltipSubtext}
                </div>
              )}
            </motion.div>
          )}

          <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-28 overflow-visible">
            <defs>
              <linearGradient id={glowGradientId} x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor="var(--text-primary)" stopOpacity="0.08" />
                <stop offset="100%" stopColor="var(--text-primary)" stopOpacity="0.0" />
              </linearGradient>
              <linearGradient id={lineAreaGradientId} x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor="var(--text-primary)" stopOpacity="0.09" />
                <stop offset="100%" stopColor="var(--text-primary)" stopOpacity="0.0" />
              </linearGradient>
            </defs>

            {/* Soft Ambient Area Fill */}
            <path d={areaD} fill={`url(#${lineAreaGradientId})`} />

            {/* Active Vertical Column Glow */}
            <rect
              x={activePoint.x - 14}
              y={0}
              width={28}
              height={height}
              rx={6}
              fill={`url(#${glowGradientId})`}
              className="transition-all duration-300 pointer-events-none"
            />

            {/* Smooth Spline Trajectory */}
            <path
              d={pathD}
              fill="none"
              stroke="var(--text-primary)"
              strokeWidth="1.75"
              strokeLinecap="round"
              strokeLinejoin="round"
              className="opacity-90"
            />

            {/* Interactive Node Dots */}
            {points.map((pt, i) => {
              const isActive = activeIndex === i;
              return (
                <g key={i} className="cursor-pointer" onClick={() => setActiveIndex(i)}>
                  <circle
                    cx={pt.x}
                    cy={pt.y}
                    r={isActive ? 4 : 2.5}
                    className={cn(
                      'transition-all duration-200',
                      isActive
                        ? 'fill-card stroke-text-primary'
                        : 'fill-card stroke-border/90 hover:stroke-text-secondary'
                    )}
                    strokeWidth={isActive ? 2 : 1.25}
                  />
                  {isActive && (
                    <circle
                      cx={pt.x}
                      cy={pt.y}
                      r="7"
                      fill="none"
                      stroke="var(--text-primary)"
                      strokeWidth="1"
                      strokeOpacity="0.25"
                    />
                  )}
                </g>
              );
            })}
          </svg>

          {/* Month Labels */}
          <div className="flex items-center justify-between text-[10.5px] font-mono text-text-muted pt-2 px-1 border-t border-border/30">
            {nodes.map((n, i) => (
              <button
                key={i}
                type="button"
                onClick={() => setActiveIndex(i)}
                className={cn(
                  'transition-colors cursor-pointer hover:text-text-primary',
                  activeIndex === i ? 'text-text-primary font-medium' : 'text-text-muted/70'
                )}
              >
                {n.label}
              </button>
            ))}
          </div>
        </div>
      </div>
    );
  }
);

TactileMetricCard.displayName = 'TactileMetricCard';

// ─── 2. TACTILE BAR CARD (INCOME & RECESSED WELL CHANNELS) ────────────────────

export interface BarMetricPoint {
  label: string;
  value: number; // 0 to 100
  amountFormatted?: string;
  isHighlighted?: boolean;
}

export interface TactileBarCardProps extends React.HTMLAttributes<HTMLDivElement> {
  title?: string;
  periodLabel?: string;
  value?: string;
  deltaText?: string;
  deltaSubtext?: string;
  bars?: BarMetricPoint[];
  averageThreshold?: {
    value: number; // 0 to 100
    label: string; // e.g. "Avg $7,500"
  };
  onMoreClick?: () => void;
  onPeriodClick?: () => void;
}

const DEFAULT_BARS: BarMetricPoint[] = [
  { label: 'Sun', value: 35, amountFormatted: '$110' },
  { label: 'Mon', value: 65, amountFormatted: '$190' },
  { label: 'Tue', value: 88, amountFormatted: '$237', isHighlighted: true },
  { label: 'Wed', value: 50, amountFormatted: '$150' },
  { label: 'Thu', value: 72, amountFormatted: '$210' },
  { label: 'Fri', value: 40, amountFormatted: '$130' },
  { label: 'Sat', value: 30, amountFormatted: '$95' },
];

export const TactileBarCard = React.forwardRef<HTMLDivElement, TactileBarCardProps>(
  (
    {
      className,
      title = 'Income',
      periodLabel = 'This Month',
      value = '$12,532',
      deltaText = '+12%',
      deltaSubtext = 'vs last month',
      bars = DEFAULT_BARS,
      averageThreshold = { value: 55, label: 'Avg $7,500' },
      onMoreClick,
      onPeriodClick,
      ...props
    },
    ref
  ) => {
    const [selectedBar, setSelectedBar] = React.useState<BarMetricPoint | null>(
      bars.find((b) => b.isHighlighted) || bars[2]
    );

    return (
      <div
        ref={ref}
        className={cn(
          'relative w-full rounded-[26px] border border-border/70 bg-card text-text-primary p-6',
          'shadow-tactile select-none transition-colors overflow-hidden flex flex-col justify-between',
          className
        )}
        {...props}
      >
        {/* Header: Title, Period & Actions */}
        <div className="flex items-center justify-between gap-3 pb-4">
          <div className="flex items-center gap-2">
            <div className="w-6 h-6 rounded-md bg-secondary/80 border border-border/60 flex items-center justify-center text-text-muted">
              <BarChart2 className="w-3.5 h-3.5" />
            </div>
            <span className="text-xs font-medium tracking-tight text-text-primary">{title}</span>
          </div>

          <div className="flex items-center gap-1.5">
            <button
              type="button"
              onClick={onPeriodClick}
              className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-md text-[11px] font-mono bg-secondary/60 border border-border/60 text-text-secondary hover:text-text-primary hover:bg-secondary/90 transition-colors cursor-pointer"
            >
              <span>{periodLabel}</span>
              <ChevronDown className="w-3 h-3 text-text-muted" />
            </button>
            <button
              type="button"
              onClick={onMoreClick}
              aria-label="More options"
              className="w-6 h-6 rounded-md inline-flex items-center justify-center text-text-muted hover:text-text-primary hover:bg-secondary/60 transition-colors cursor-pointer"
            >
              <MoreHorizontal className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>

        {/* Metric Value Row */}
        <div className="flex items-baseline justify-between gap-3 pb-4">
          <div className="text-2xl sm:text-3xl font-mono font-medium tracking-tight text-text-primary">
            {value}
          </div>
          <div className="flex items-center gap-1.5 text-right">
            <span className="inline-flex items-center gap-0.5 px-2 py-0.5 rounded-full text-[10px] font-mono font-medium bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20">
              <ArrowUpRight className="w-3 h-3" />
              {deltaText}
            </span>
            <span className="text-[10px] text-text-muted hidden sm:inline">{deltaSubtext}</span>
          </div>
        </div>

        {/* Bars Container with Recessed Well Channels & Threshold Line */}
        <div className="relative w-full h-36 pt-3 pb-1">
          {/* Horizontal Dashed Threshold Line */}
          {averageThreshold && (
            <div
              className="absolute left-0 right-0 z-20 flex items-center pointer-events-none"
              style={{ bottom: `${averageThreshold.value * 0.95}px` }}
            >
              <div className="px-1.5 py-0.5 rounded text-[9.5px] font-mono bg-card/90 text-text-muted border border-border/60 shadow-2xs mr-2">
                {averageThreshold.label}
              </div>
              <div className="flex-1 border-b border-dashed border-border/60" />
            </div>
          )}

          {/* Bar Columns inside Recessed Channels */}
          <div className="flex items-end justify-between gap-2.5 h-full px-1">
            {bars.map((bar, i) => {
              const isHighlighted = bar.isHighlighted || selectedBar?.label === bar.label;
              return (
                <div
                  key={i}
                  onClick={() => setSelectedBar(bar)}
                  className="flex-1 flex flex-col items-center justify-end h-full group cursor-pointer relative"
                >
                  {/* Floating Tag above highlighted bar */}
                  {isHighlighted && bar.amountFormatted && (
                    <motion.div
                      initial={{ opacity: 0, y: 2 }}
                      animate={{ opacity: 1, y: 0 }}
                      className="absolute -top-7 z-30 px-2 py-0.5 rounded-md text-[10px] font-mono font-medium bg-card border border-border text-text-primary shadow-tactile whitespace-nowrap"
                    >
                      {bar.amountFormatted}
                    </motion.div>
                  )}

                  {/* Recessed Track Well */}
                  <div className="w-full max-w-[22px] h-full bg-secondary/35 rounded-t-lg flex flex-col justify-end overflow-hidden p-0.5 border-t border-x border-border/25">
                    {/* Filled Bar */}
                    <div
                      className={cn(
                        'w-full rounded-t-md transition-all duration-200',
                        isHighlighted
                          ? 'bg-text-primary/90 dark:bg-[#eae5dc] shadow-2xs'
